#[cfg(test)]
mod tests {
    use rigorix_engine::capacity_ledger::domain::IdempotencyKey;

    #[test]
    fn test_idempotencykey_is_defined() {
        let key = IdempotencyKey::new("reserve-1");
        assert_eq!(key.as_str(), "reserve-1");
        assert_eq!(key.to_string(), "reserve-1");
    }

    #[test]
    fn test_idempotencykey_interacts_with_none() {
        // No dependencies: a key is a stable, comparable retry identity.
        assert_eq!(IdempotencyKey::new("k"), IdempotencyKey::new("k"));
        assert_ne!(IdempotencyKey::new("k"), IdempotencyKey::new("K"));

        let from_uuid = IdempotencyKey::from_uuid(uuid::Uuid::nil());
        assert_eq!(from_uuid.as_str(), "00000000-0000-0000-0000-000000000000");
    }
}
